cd /workspace && python3 - <<'EOF'
import json, sys, math
# int digit limit behavior
print(sys.get_int_max_str_digits())
try:
    json.loads('{"a":' + '1'*4301 + '}')
    print("4301-digit int: no error")
except Exception as e:
    print("4301-digit int:", type(e).__name__, e)
try:
    json.loads('{"a":' + '1'*4300 + '}')
    print("4300-digit int: ok")
except Exception as e:
    print("4300-digit int:", type(e).__name__, e)
# float long digits
try:
    v = float('1.' + '2'*5000)
    print("float long frac ok", v)
except Exception as e:
    print("float long frac:", type(e).__name__, e)
try:
    v = float('1' + '0'*5000 + '.5')
    print("float long int ok", v)
except Exception as e:
    print("float long int:", type(e).__name__, e)
try:
    v = float('1e400')
    print("float 1e400:", v, math.isfinite(v))
except Exception as e:
    print("float 1e400:", type(e).__name__, e)
try:
    v = float('1e-400')
    print("float 1e-400:", v)
except Exception as e:
    print("float 1e-400:", type(e).__name__, e)
try:
    v = float('1e99999999999999999999')
    print("float huge exp:", v)
except Exception as e:
    print("float huge exp:", type(e).__name__, e)
from decimal import Decimal
try:
    v = float(Decimal('1.' + '2'*5000))
    print("decimal fallback ok", v)
except Exception as e:
    print("decimal fallback:", type(e).__name__, e)
try:
    v = float(Decimal('1e400'))
    print("decimal 1e400:", v)
except Exception as e:
    print("decimal 1e400:", type(e).__name__, e)
try:
    v = float(Decimal('1e-999999999999999999999'))
    print("decimal tiny:", v)
except Exception as e:
    print("decimal tiny:", type(e).__name__, e)
EOF

cd /workspace && python3 - <<'EOF'
import json
# parse_float called for ints? parse_int default behavior with huge tokens
seen = {}
def pf(t):
    seen['pf'] = seen.get('pf',0)+1
    return float(t)
try:
    json.loads('{"a":1e400}', parse_float=pf)
except Exception as e:
    print("1e400 via hook:", type(e).__name__, e, seen)
try:
    json.loads('{"a":01}', parse_float=pf)
except Exception as e:
    print("01:", type(e).__name__, e)
try:
    json.loads('{"a":00}')
except Exception as e:
    print("00:", type(e).__name__, e)
try:
    json.loads('\ufeff{}')
except Exception as e:
    print("BOM:", type(e).__name__, e)
try:
    json.loads('{}\n  ')
    print("trailing ws ok")
except Exception as e:
    print("trailing ws:", type(e).__name__, e)
try:
    json.loads('{}{}')
except Exception as e:
    print("trailing json:", type(e).__name__, e)
# recursion depth
try:
    json.loads('['*2000 + ']'*2000)
    print("depth 2000 ok")
except Exception as e:
    print("depth 2000:", type(e).__name__, e)
try:
    json.loads('['*70 + ']'*70)
    print("depth 70 ok")
except Exception as e:
    print("depth 70:", type(e).__name__, e)
EOF
